def calculate_flips(n):
    N = 2 * n + 1
    # Modular inverse of 2 mod N. Since N is odd, 2 is invertible.
    # We use Fermat's Little Theorem if N is prime, or extended Euclidean algorithm otherwise.
    # For small N, we can find it directly.
    def inverse_2(m):
        for x in range(1, m):
            if (2 * x) % m == 1:
                return x
        return None

    inv2 = inverse_2(N)
    if inv2 is None:
        return "Error: 2 is not invertible mod N"

    flip_counts = [0] * N

    # P_i = (i-1)(i+2) * inv2 mod N, for i = 1 to N
    for i in range(1, N + 1):
        # The formula derived is P_i = (i-1)(i+2) / 2 mod N
        numerator = (i - 1) * (i + 2)
        P_i = (numerator * inv2) % N

        flip_counts[P_i] += 1

    # Count how many coins were flipped an odd number of times
    heads_down_count = 0
    for count in flip_counts:
        if count % 2 != 0:
            heads_down_count += 1

    return heads_down_count

test_cases = [1, 2, 3] # N=3, N=5, N=7
results = {}
for n in test_cases:
    results[n] = calculate_flips(n)

print(f"N=3 (n=1): Heads down = {results[1]}")
